class MsRadioGroup extends HTMLElement{constructor(){super(),this.attachShadow({mode:"open"}),this.shadowRoot.innerHTML="\n      <style>\n        :host {\n          display: flex;\n          flex-direction: row; /* Por padrão, os botões serão alinhados horizontalmente */\n          gap: 8px; /* Espaçamento entre os botões */\n        }\n\n        :host([column]) {\n          flex-direction: column; /* Alinhamento vertical quando o atributo 'column' está presente */\n        }\n      </style>\n      <slot ></slot>\n    "}connectedCallback(){this.updateRadios(),this.addEventListener("click",this.onRadioClick.bind(this))}updateRadios(){Array.from(this.querySelectorAll("ms-radio")).forEach(((e,t)=>{e.setAttribute("index",t),e.hasAttribute("checked")&&this.selectRadio(e)}))}onRadioClick(e){const t=e.target.closest("ms-radio");t&&!t.hasAttribute("disabled")&&this.selectRadio(t)}selectRadio(e){Array.from(this.querySelectorAll("ms-radio")).forEach((t=>{t===e?(t.setAttribute("checked",""),this.dispatchChangeEvent(t)):t.removeAttribute("checked")}))}dispatchChangeEvent(e){const t={value:e.getAttribute("data-label")||e.textContent.trim(),index:parseInt(e.getAttribute("index")),data:e.getAttribute("data")||null};this.dispatchEvent(new CustomEvent("change",{detail:t}))}checked(e){const t=this.querySelectorAll("ms-radio");t[e]&&this.selectRadio(t[e])}enable(e){const t=this.querySelector(`ms-radio:nth-child(${e+1})`);t&&t.removeAttribute("disabled")}disable(e){const t=this.querySelector(`ms-radio:nth-child(${e+1})`);t&&t.setAttribute("disabled","")}}class MsRadio extends HTMLElement{constructor(){super(),this.attachShadow({mode:"open"}),this.shadowRoot.innerHTML='\n      <style>\n        :host {\n          display: flex;\n          align-items: center;\n          cursor: pointer;\n          font-size: 11px;\n        }\n\n        :host([disabled]) {\n          color: #a0a0a0;\n          pointer-events: none;\n        }\n\n        .circle {\n          width: 13px;\n          height: 13px;\n          margin: 3px;\n          border: 2px solid var(--psfx-ui-borda-radio-color);\n          border-radius: 50%;\n          display: flex;\n          align-items: center;\n          justify-content: center;\n          background-color: var(--psfx-ui-bg-radio-color);\n        }\n\n        .circle:hover {\n          border: 2px solid var(--psfx-ui-borda-radio-hover-color);\n        }\n\n        :host([disabled]) .circle {\n          border: 2px solid var(--psfx-texto-disbled-color);\n          background-color: var(-psfx-bg-detalhes-claro-color);\n        }\n\n        .circle.checked {\n          border: 4px solid var(--psfx-ui-borda-radio-cchecked-color);\n        }\n\n        :host(:hover) .circle.checked {\n          border: 4px solid var(--psfx-texto-color-2);\n        }\n\n        :host([disabled]) .circle.checked {\n          background-color: var(--psfx-ui-bg-radio-color);\n          border: 4px solid var(--psfx-texto-disbled-color);\n        }\n      \n        :host(:hover) .circle {\n          border: 2px solid var(--psfx-ui-borda-radio-hover-color);\n        }\n      </style>\n      <div class="circle"></div>\n      <div class="rdtexto"></div>\n    '}connectedCallback(){this.updateLabel(),this.hasAttribute("checked")&&this.shadowRoot.querySelector(".circle").classList.add("checked")}updateLabel(){const e=this.shadowRoot.querySelector(".rdtexto"),t=this.getAttribute("data-label")||this.textContent.trim()||"";e.textContent=t}static get observedAttributes(){return["checked","disabled","data-label"]}attributeChangedCallback(e,t,o){const r=this.shadowRoot.querySelector(".circle");"checked"===e&&r.classList.toggle("checked",null!==o),"data-label"===e&&this.updateLabel()}}customElements.define("ms-radio-group",MsRadioGroup),customElements.define("ms-radio",MsRadio);